($q$Simple Syrup$q$, 1600, $q$ml$q$, 504, $q$Fridge, sealed bottle$q$, ARRAY[$q$Syrup$q$]::text[]),
($q$Sour Mix$q$, 1500, $q$ml$q$, 48, $q$Fridge, sealed bottle$q$, ARRAY[$q$Mix$q$]::text[]),
($q$Spiced Syrup$q$, 780, $q$ml$q$, 504, $q$Fridge, sealed bottle$q$, ARRAY[$q$Infuse$q$, $q$Syrup$q$, $q$Strain$q$]::text[]),
($q$Strawberry Shrub$q$, 1000, $q$ml$q$, 1344, $q$Fridge, sealed bottle$q$, ARRAY[$q$Infuse$q$, $q$Strain$q$, $q$Mix$q$]::text[]),
($q$Strawberry Syrup$q$, 1000, $q$ml$q$, 336, $q$Fridge, sealed bottle$q$, ARRAY[$q$Infuse$q$, $q$Syrup$q$, $q$Strain$q$]::text[]),
($q$Strawberry-Infused Campari$q$, 750, $q$ml$q$, 2160, $q$Fridge, sealed labelled bottle$q$, ARRAY[$q$Infuse$q$, $q$Strain$q$]::text[]),
($q$Super Lemon Juice$q$, 1900, $q$ml$q$, 120, $q$Fridge, sealed bottle, shake before use$q$, ARRAY[$q$Infuse$q$, $q$Blend$q$, $q$Strain$q$, $q$Mix$q$]::text[]),
($q$Super Lime Juice$q$, 1900, $q$ml$q$, 120, $q$Fridge, sealed bottle, shake before use$q$, ARRAY[$q$Infuse$q$, $q$Blend$q$, $q$Strain$q$, $q$Mix$q$]::text[]),
($q$Tea-Infused Vermouth$q$, 680, $q$ml$q$, 672, $q$Fridge, sealed labelled bottle$q$, ARRAY[$q$Infuse$q$, $q$Strain$q$]::text[]),
($q$Tepache$q$, 2000, $q$ml$q$, 168, $q$Fridge, bottle with lid loose to vent gas$q$, ARRAY[$q$Ferment$q$, $q$Strain$q$]::text[]),
($q$Thyme Syrup$q$, 800, $q$ml$q$, 504, $q$Fridge, sealed bottle$q$, ARRAY[$q$Syrup$q$, $q$Infuse$q$, $q$Strain$q$]::text[]),
($q$Tom and Jerry Batter$q$, 1500, $q$g$q$, 24, $q$Fridge, covered; stir before use$q$, ARRAY[$q$Mix$q$]::text[]),
($q$Tonic Syrup$q$, 1400, $q$ml$q$, 336, $q$Fridge, sealed bottle$q$, ARRAY[$q$Infuse$q$, $q$Strain$q$, $q$Syrup$q$]::text[]),
($q$Vanilla Syrup$q$, 1600, $q$ml$q$, 504, $q$Fridge, sealed bottle$q$, ARRAY[$q$Syrup$q$, $q$Infuse$q$, $q$Strain$q$]::text[]),
($q$Vanilla Tincture$q$, 240, $q$ml$q$, 8760, $q$Room temperature, dropper bottle, away from light$q$, ARRAY[$q$Infuse$q$, $q$Strain$q$]::text[]),
($q$Vanilla-Infused Vodka$q$, 700, $q$ml$q$, 8760, $q$Room temperature, sealed labelled bottle$q$, ARRAY[$q$Infuse$q$, $q$Strain$q$]::text[]);
INSERT INTO "seed_step" VALUES
($q$Acid-Adjusted Orange Juice$q$, 0, $q$Juice the oranges and fine strain the juice.$q$),
($q$Acid-Adjusted Orange Juice$q$, 1, $q$Weigh the acids accurately and add them to the juice.$q$),
($q$Acid-Adjusted Orange Juice$q$, 2, $q$Stir or shake until the powders have fully dissolved.$q$),
($q$Acid-Adjusted Orange Juice$q$, 3, $q$Bottle, label with the date and keep in the fridge. Best on the day it is made.$q$),
($q$Agave Syrup Mix$q$, 0, $q$Measure the agave syrup and warm water into a container.$q$),
($q$Agave Syrup Mix$q$, 1, $q$Stir or shake until evenly mixed.$q$),
($q$Agave Syrup Mix$q$, 2, $q$Bottle, label with the date and keep in the fridge.$q$),
($q$Bacon Fat-Washed Bourbon$q$, 0, $q$Cook smoked bacon and strain the rendered fat. Weigh out the warm, liquid fat.$q$),
($q$Bacon Fat-Washed Bourbon$q$, 1, $q$Combine the fat and bourbon in a wide container and stir. Leave at room temperature.$q$),
($q$Bacon Fat-Washed Bourbon$q$, 2, $q$Freeze until the fat has set solid.$q$),
($q$Bacon Fat-Washed Bourbon$q$, 3, $q$Remove the fat and strain the cold bourbon through a coffee filter. Bottle, label as containing pork and keep in the fridge.$q$),
($q$Banana Syrup$q$, 0, $q$Stir the sugar into the hot water until dissolved.$q$),
($q$Banana Syrup$q$, 1, $q$Add the sliced banana, cover and steep in the fridge.$q$),
($q$Banana Syrup$q$, 2, $q$Strain through a fine sieve and let it drip. Do not press the fruit, which makes the syrup cloudy and starchy.$q$),
($q$Banana Syrup$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Banana-Infused Rum$q$, 0, $q$Combine the sliced banana and rum in a clean jar and seal.$q$),
($q$Banana-Infused Rum$q$, 1, $q$Infuse in the fridge for 24 hours, shaking once or twice.$q$),
($q$Banana-Infused Rum$q$, 2, $q$Strain through a fine sieve, then a coffee filter, without pressing the fruit.$q$),
($q$Banana-Infused Rum$q$, 3, $q$Bottle, label and keep in the fridge.$q$),
($q$Basil Syrup$q$, 0, $q$Blanch the basil leaves in boiling water, then move them straight into iced water to keep them green.$q$),
($q$Basil Syrup$q$, 1, $q$Squeeze the leaves dry and blend with the cold simple syrup until smooth.$q$),
($q$Basil Syrup$q$, 2, $q$Strain through a fine cloth or coffee filter.$q$),
($q$Basil Syrup$q$, 3, $q$Bottle and keep in the fridge. Use within a week, before the colour dulls.$q$),
($q$Beetroot Syrup$q$, 0, $q$Peel and juice the raw beetroot, then strain the juice through a fine sieve.$q$),
($q$Beetroot Syrup$q$, 1, $q$Weigh the juice and add the same weight of sugar.$q$),
($q$Beetroot Syrup$q$, 2, $q$Warm gently, stirring, just until the sugar has dissolved.$q$),
($q$Beetroot Syrup$q$, 3, $q$Cool, bottle and keep in the fridge.$q$),
($q$Bloody Mary Mix$q$, 0, $q$Combine all the ingredients in a jug or large container.$q$),
($q$Bloody Mary Mix$q$, 1, $q$Stir well, taste and adjust the heat and seasoning.$q$),
($q$Bloody Mary Mix$q$, 2, $q$Rest in the fridge so the flavours come together.$q$),
($q$Bloody Mary Mix$q$, 3, $q$Bottle and keep in the fridge. Shake before each use.$q$),
($q$Brown Butter-Washed Bourbon$q$, 0, $q$Melt the butter in a pan over medium heat and cook, swirling, until the milk solids turn golden brown and it smells nutty. Take off the heat at once.$q$),
($q$Brown Butter-Washed Bourbon$q$, 1, $q$Let the butter cool for a few minutes, then combine it with the bourbon in a wide container and stir well.$q$),
($q$Brown Butter-Washed Bourbon$q$, 2, $q$Leave at room temperature, stirring now and then.$q$),
($q$Brown Butter-Washed Bourbon$q$, 3, $q$Freeze until the butter has set solid.$q$),
($q$Brown Butter-Washed Bourbon$q$, 4, $q$Strain the cold bourbon through a coffee filter. Bottle and keep in the fridge.$q$),
($q$Brown Sugar Syrup$q$, 0, $q$Combine the brown sugar and hot water.$q$),
($q$Brown Sugar Syrup$q$, 1, $q$Stir until fully dissolved, warming gently if needed.$q$),
($q$Brown Sugar Syrup$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge.$q$),
($q$Butterfly Pea Gin$q$, 0, $q$Add the dried flowers to the gin in a clean jar or the bottle, seal and shake.$q$),
($q$Butterfly Pea Gin$q$, 1, $q$Infuse at room temperature until the gin is deep blue.$q$),
($q$Butterfly Pea Gin$q$, 2, $q$Strain through a fine sieve or coffee filter.$q$),
($q$Butterfly Pea Gin$q$, 3, $q$Bottle, label and store away from sunlight, which fades the colour.$q$),
($q$Cacao Nib-Infused Campari$q$, 0, $q$Add the cacao nibs to the Campari in a clean jar, seal and shake.$q$),
($q$Cacao Nib-Infused Campari$q$, 1, $q$Infuse at room temperature, shaking now and then. Taste and leave longer for a stronger chocolate note.$q$),
($q$Cacao Nib-Infused Campari$q$, 2, $q$Strain through a fine sieve and then a coffee filter.$q$),
($q$Cacao Nib-Infused Campari$q$, 3, $q$Bottle and label.$q$),
($q$Cane Syrup$q$, 0, $q$Combine the cane sugar and water in a pan over low heat.$q$),
($q$Cane Syrup$q$, 1, $q$Stir until completely dissolved, without boiling.$q$),
($q$Cane Syrup$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge.$q$),
($q$Chai Syrup$q$, 0, $q$Simmer the water with all the spices and the ginger, covered.$q$),
($q$Chai Syrup$q$, 1, $q$Take off the heat, add the black tea and steep.$q$),
($q$Chai Syrup$q$, 2, $q$Strain through a fine sieve.$q$),
($q$Chai Syrup$q$, 3, $q$Stir the sugar into the hot liquid until dissolved, then cool, bottle and keep in the fridge.$q$),
($q$Chamomile Syrup$q$, 0, $q$Pour the hot water over the chamomile flowers, cover and steep.$q$),
($q$Chamomile Syrup$q$, 1, $q$Strain through a fine sieve.$q$),
($q$Chamomile Syrup$q$, 2, $q$Stir the sugar into the warm tea until dissolved.$q$),
($q$Chamomile Syrup$q$, 3, $q$Cool, bottle and keep in the fridge.$q$),
($q$Chamomile-Infused Bourbon$q$, 0, $q$Add the chamomile to the bourbon in a clean jar, seal and shake.$q$),
($q$Chamomile-Infused Bourbon$q$, 1, $q$Infuse at room temperature, shaking now and then.$q$),
($q$Chamomile-Infused Bourbon$q$, 2, $q$Strain through a fine sieve and then a coffee filter, pressing the flowers lightly.$q$),
($q$Chamomile-Infused Bourbon$q$, 3, $q$Bottle and label.$q$),
($q$Champagne Acid$q$, 0, $q$Weigh the water and both acids accurately.$q$),
($q$Champagne Acid$q$, 1, $q$Stir or shake until the powders have completely dissolved and the liquid is clear.$q$),
($q$Champagne Acid$q$, 2, $q$Bottle and label clearly with the name and date.$q$),
($q$Chilli Tincture$q$, 0, $q$Wearing gloves, roughly chop the dried chillies and put them in a clean jar with the vodka.$q$),
($q$Chilli Tincture$q$, 1, $q$Seal and infuse at room temperature, shaking now and then.$q$),
($q$Chilli Tincture$q$, 2, $q$Taste a single drop diluted in water. Infuse longer for more heat.$q$),
($q$Chilli Tincture$q$, 3, $q$Strain through a coffee filter into dropper bottles and label clearly.$q$),
($q$Chilli-Infused Tequila$q$, 0, $q$Wearing gloves, halve the chillies and add them to the tequila in a clean jar.$q$),
($q$Chilli-Infused Tequila$q$, 1, $q$Infuse at room temperature, tasting every 5 minutes. Fresh chilli infuses fast.$q$),
($q$Chilli-Infused Tequila$q$, 2, $q$Strain through a fine sieve as soon as the heat is where you want it.$q$),
($q$Chilli-Infused Tequila$q$, 3, $q$Bottle and label. If it is too hot, blend it back with plain tequila.$q$),
($q$Cinnamon Syrup$q$, 0, $q$Bring the water and broken cinnamon sticks to a boil, then simmer gently with the lid on.$q$),
($q$Cinnamon Syrup$q$, 1, $q$Take off the heat, add the sugar and stir until dissolved.$q$),
($q$Cinnamon Syrup$q$, 2, $q$Cover and leave to steep.$q$),
($q$Cinnamon Syrup$q$, 3, $q$Strain through a fine sieve, bottle and keep in the fridge.$q$),
($q$Cinnamon Tincture$q$, 0, $q$Break up the cinnamon sticks and put them in a clean jar with the vodka.$q$),
($q$Cinnamon Tincture$q$, 1, $q$Seal and infuse at room temperature for 5 days, shaking daily. Taste from day 3; it turns woody and astringent if left too long.$q$),
($q$Cinnamon Tincture$q$, 2, $q$Strain through a coffee filter into dropper or atomiser bottles and label.$q$),
($q$Citric Acid Solution (10%)$q$, 0, $q$Weigh the citric acid and the water accurately (900 ml of water weighs 900 g).$q$),
($q$Citric Acid Solution (10%)$q$, 1, $q$Stir or shake until the powder has completely dissolved and the liquid is clear.$q$),
($q$Citric Acid Solution (10%)$q$, 2, $q$Bottle and label clearly with the name, strength and date.$q$),
($q$Citrus Foam$q$, 0, $q$Whisk the egg white, lemon juice, syrup and water together lightly, just to combine.$q$),
($q$Citrus Foam$q$, 1, $q$Fine strain into a 500 ml cream whipper so nothing blocks the nozzle. Do not fill past the maximum line.$q$),
($q$Citrus Foam$q$, 2, $q$Seal, charge with one nitrous oxide (N2O) cartridge and shake hard. Add a second charge if the foam is loose.$q$),
($q$Citrus Foam$q$, 3, $q$Chill for at least an hour before use.$q$),
($q$Citrus Foam$q$, 4, $q$Shake, hold upside down and dispense onto the drink. Keep in the fridge, use within a day and tell guests it contains egg.$q$),
($q$Coconut Cream Mix$q$, 0, $q$Warm the tins in hot water so the coconut fat softens, then empty them into a blender or jug.$q$),
($q$Coconut Cream Mix$q$, 1, $q$Blend or whisk until completely smooth.$q$),
($q$Coconut Cream Mix$q$, 2, $q$Pour into squeeze bottles and keep in the fridge. Let it warm slightly and shake before service.$q$),
($q$Coconut Fat-Washed Rum$q$, 0, $q$Melt the coconut oil gently and pour it into a wide container with the rum. Stir or shake well.$q$),
($q$Coconut Fat-Washed Rum$q$, 1, $q$Leave at room temperature, shaking now and then.$q$),
($q$Coconut Fat-Washed Rum$q$, 2, $q$Freeze until the fat has set into a solid layer.$q$),
($q$Coconut Fat-Washed Rum$q$, 3, $q$Lift off or pierce the fat cap and strain the cold rum through a coffee filter. Bottle and keep in the fridge.$q$),
($q$Coconut Syrup$q$, 0, $q$Shake the tin well, then combine the coconut milk, sugar and salt in a pan.$q$),
($q$Coconut Syrup$q$, 1, $q$Warm over low heat, stirring, until the sugar has dissolved. Do not boil or the milk can split.$q$),
($q$Coconut Syrup$q$, 2, $q$Cool, bottle and keep in the fridge. The fat sets when cold; warm the bottle briefly and shake before use.$q$),
($q$Coffee Syrup$q$, 0, $q$Brew the coffee strong and measure it while hot.$q$),
($q$Coffee Syrup$q$, 1, $q$Stir in the sugar until fully dissolved.$q$),
($q$Coffee Syrup$q$, 2, $q$Cool, bottle and keep in the fridge.$q$),
($q$Coffee-Infused Campari$q$, 0, $q$Add the whole coffee beans to the Campari in a clean jar or the bottle and seal.$q$),
($q$Coffee-Infused Campari$q$, 1, $q$Infuse at room temperature. Taste after 12 hours and strain early if the coffee is strong enough.$q$),
($q$Coffee-Infused Campari$q$, 2, $q$Strain through a fine sieve.$q$),
($q$Coffee-Infused Campari$q$, 3, $q$Bottle and label.$q$),
($q$Cold Brew Concentrate$q$, 0, $q$Put the ground coffee in a clean container, add the cold water and stir so all the grounds are wet.$q$),
($q$Cold Brew Concentrate$q$, 1, $q$Cover and steep in the fridge.$q$),
($q$Cold Brew Concentrate$q$, 2, $q$Strain through a fine sieve, then through a paper coffee filter.$q$),
($q$Cold Brew Concentrate$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Cucumber Syrup$q$, 0, $q$Juice the cucumber with the skin on and strain through a fine sieve or cloth.$q$),
($q$Cucumber Syrup$q$, 1, $q$Weigh the juice and add the same weight of sugar.$q$),
($q$Cucumber Syrup$q$, 2, $q$Stir or blend without heat until the sugar has dissolved.$q$),
($q$Cucumber Syrup$q$, 3, $q$Bottle and keep in the fridge. Use within four days; the fresh flavour fades quickly.$q$),
($q$Cucumber-Infused Gin$q$, 0, $q$Combine the sliced cucumber and gin in a clean jar and seal.$q$),
($q$Cucumber-Infused Gin$q$, 1, $q$Infuse in the fridge.$q$),
($q$Cucumber-Infused Gin$q$, 2, $q$Strain through a fine sieve and then a coffee filter, without pressing the cucumber.$q$),
($q$Cucumber-Infused Gin$q$, 3, $q$Bottle, label and keep in the fridge.$q$),
($q$Demerara Syrup$q$, 0, $q$Combine the demerara sugar and hot water in a pan or heatproof container.$q$),
($q$Demerara Syrup$q$, 1, $q$Stir over low heat until fully dissolved. The large crystals take longer than white sugar.$q$),
($q$Demerara Syrup$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge.$q$),
($q$Don's Mix$q$, 0, $q$Juice the grapefruit and fine strain it.$q$),
($q$Don's Mix$q$, 1, $q$Combine the juice with the cinnamon syrup and stir.$q$),
($q$Don's Mix$q$, 2, $q$Bottle, label with the date and keep in the fridge. Shake before use.$q$),
($q$Don's Spices No. 2$q$, 0, $q$Measure equal parts vanilla syrup and allspice dram into a bottle.$q$),
($q$Don's Spices No. 2$q$, 1, $q$Shake to combine, label with the date and keep in the fridge.$q$),
($q$Earl Grey Syrup$q$, 0, $q$Pour the hot water over the tea and steep. Do not go much longer or the syrup turns bitter.$q$),
($q$Earl Grey Syrup$q$, 1, $q$Strain out the tea without squeezing the leaves.$q$),
($q$Earl Grey Syrup$q$, 2, $q$Stir the sugar into the hot tea until dissolved.$q$),
($q$Earl Grey Syrup$q$, 3, $q$Cool, bottle and keep in the fridge.$q$),
($q$Earl Grey-Infused Gin$q$, 0, $q$Add the loose tea to the gin in a clean jar or the bottle, seal and shake.$q$),
($q$Earl Grey-Infused Gin$q$, 1, $q$Infuse at room temperature.$q$),
($q$Earl Grey-Infused Gin$q$, 2, $q$Strain through a fine sieve and then a coffee filter. Do not squeeze the leaves.$q$),
($q$Earl Grey-Infused Gin$q$, 3, $q$Bottle and label.$q$),
($q$Eggnog Base$q$, 0, $q$Blend the eggs on low speed until smooth.$q$),
($q$Eggnog Base$q$, 1, $q$With the blender running, add the sugar slowly and blend until dissolved.$q$),
($q$Eggnog Base$q$, 2, $q$Add the nutmeg, milk and cream and blend just until combined.$q$),
($q$Eggnog Base$q$, 3, $q$Bottle and chill thoroughly before serving. Contains raw egg; keep cold, use within two days and tell guests.$q$),
($q$Elderflower Cordial$q$, 0, $q$Pour the boiling water over the sugar in a large clean bowl or pan and stir until dissolved. Leave to cool until warm.$q$),
($q$Elderflower Cordial$q$, 1, $q$Add the lemon zest and slices, the citric acid and the elderflower heads. Stir, cover and steep somewhere cool.$q$),
($q$Elderflower Cordial$q$, 2, $q$Strain through a scalded muslin cloth.$q$),
($q$Elderflower Cordial$q$, 3, $q$Pour into sterilised bottles, seal and keep in the fridge. Freeze in tubs to keep it longer.$q$),
($q$Falernum Syrup$q$, 0, $q$Simmer the water with the ginger, almonds, cloves and allspice, covered.$q$),
($q$Falernum Syrup$q$, 1, $q$Take off the heat, add the sugar and stir until dissolved.$q$),
($q$Falernum Syrup$q$, 2, $q$Add the lime zest, cover and steep as it cools.$q$),
($q$Falernum Syrup$q$, 3, $q$Strain through a fine sieve and cloth, bottle and keep in the fridge.$q$),
($q$Fassionola$q$, 0, $q$Heat the water and sugar, stirring, until dissolved.$q$),
($q$Fassionola$q$, 1, $q$Add the strawberries, raspberries and hibiscus and simmer very gently.$q$),
($q$Fassionola$q$, 2, $q$Take off the heat, cover and steep as it cools.$q$),
($q$Fassionola$q$, 3, $q$Strain through a fine sieve without pressing hard, then stir in the passion fruit purée.$q$),
($q$Fassionola$q$, 4, $q$Bottle and keep in the fridge. Shake before use.$q$),
($q$Ginger Cordial$q$, 0, $q$Simmer the ginger in the water, covered.$q$),
($q$Ginger Cordial$q$, 1, $q$Strain through a fine sieve, pressing the ginger firmly.$q$),
($q$Ginger Cordial$q$, 2, $q$Stir the sugar into the hot liquid until dissolved, then leave to cool.$q$),
($q$Ginger Cordial$q$, 3, $q$Stir in the lemon juice, bottle and keep in the fridge.$q$),
($q$Ginger Syrup$q$, 0, $q$Wash the ginger (no need to peel), juice it and strain the juice through a fine sieve.$q$),
($q$Ginger Syrup$q$, 1, $q$Weigh the juice and add the same weight of sugar.$q$),
($q$Ginger Syrup$q$, 2, $q$Blend or stir without heat until the sugar has fully dissolved.$q$),
($q$Ginger Syrup$q$, 3, $q$Bottle and keep in the fridge. Shake before use; the heat fades after about two weeks.$q$),
($q$Gomme Syrup$q$, 0, $q$Stir the gum arabic into 150 ml of warm water. Cover and leave until it has fully hydrated into a thick, sticky paste, stirring now and then.$q$),
($q$Gomme Syrup$q$, 1, $q$Heat the sugar with the remaining 300 ml of water over low heat, stirring until dissolved.$q$),
($q$Gomme Syrup$q$, 2, $q$Add the gum mixture and stir over low heat until smooth. Do not boil. Skim any foam from the surface.$q$),
($q$Gomme Syrup$q$, 3, $q$Strain through a fine sieve, cool, bottle and keep in the fridge.$q$),
($q$Grapefruit Sherbet$q$, 0, $q$Muddle the grapefruit peels with the sugar, cover and rest until the sugar is wet and oily.$q$),
($q$Grapefruit Sherbet$q$, 1, $q$Add the grapefruit juice and stir until all the sugar has dissolved.$q$),
($q$Grapefruit Sherbet$q$, 2, $q$Strain out the peels, pressing them well.$q$),
($q$Grapefruit Sherbet$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Grenadine$q$, 0, $q$Warm the pomegranate juice over low heat until just hot. Do not boil, which dulls the fresh flavour.$q$),
($q$Grenadine$q$, 1, $q$Add the sugar and stir until dissolved.$q$),
($q$Grenadine$q$, 2, $q$Take off the heat, stir in the pomegranate molasses and orange flower water and leave to cool.$q$),
($q$Grenadine$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Hibiscus Syrup$q$, 0, $q$Pour the hot water over the dried hibiscus, cover and steep.$q$),
($q$Hibiscus Syrup$q$, 1, $q$Strain through a fine sieve, pressing the flowers lightly.$q$),
($q$Hibiscus Syrup$q$, 2, $q$Stir the sugar into the warm liquid until dissolved.$q$),
($q$Hibiscus Syrup$q$, 3, $q$Cool, bottle and keep in the fridge.$q$),
($q$Honey Syrup$q$, 0, $q$Weigh the honey into a container and add the warm water.$q$),
($q$Honey Syrup$q$, 1, $q$Stir until the honey has fully blended into the water. Do not boil; heat drives off the honey's aroma.$q$),
($q$Honey Syrup$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge.$q$),
($q$Honey Syrup (1:1)$q$, 0, $q$Weigh equal amounts of honey and warm water into a container.$q$),
($q$Honey Syrup (1:1)$q$, 1, $q$Stir until fully blended. Do not boil.$q$),
($q$Honey Syrup (1:1)$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge. The extra water means it keeps for less time than 2:1 honey syrup.$q$),
($q$Honey-Ginger Syrup$q$, 0, $q$Combine the honey, water and sliced ginger in a pan and bring to a boil.$q$),
($q$Honey-Ginger Syrup$q$, 1, $q$Lower the heat and simmer gently.$q$),
($q$Honey-Ginger Syrup$q$, 2, $q$Take off the heat, cover and leave to steep in the fridge overnight.$q$),
($q$Honey-Ginger Syrup$q$, 3, $q$Strain out the ginger, pressing lightly, then bottle and keep in the fridge.$q$),
($q$Horchata$q$, 0, $q$Rinse the rice, then soak it with the cinnamon in the water, covered, in the fridge.$q$),
($q$Horchata$q$, 1, $q$Blend the rice, cinnamon and soaking water until very smooth.$q$),
($q$Horchata$q$, 2, $q$Strain through a fine cloth or nut milk bag, squeezing well.$q$),
($q$Horchata$q$, 3, $q$Stir in the sugar and vanilla until dissolved. Bottle and keep in the fridge.$q$),
($q$Hot Buttered Rum Batter$q$, 0, $q$Let the butter soften at room temperature.$q$),
($q$Hot Buttered Rum Batter$q$, 1, $q$Beat the butter with the sugar, spices, vanilla and salt until smooth and evenly mixed.$q$),
($q$Hot Buttered Rum Batter$q$, 2, $q$Pack into a tub or roll into a log in baking paper, and keep in the fridge.$q$),
($q$Hot Buttered Rum Batter$q$, 3, $q$To serve, stir about 25 g of batter with 50 ml of aged rum and 120 ml of hot water.$q$),
($q$House Ginger Beer$q$, 0, $q$Juice the ginger and strain it through a fine cloth so no fibre is left to block the carbonator.$q$),
($q$House Ginger Beer$q$, 1, $q$Stir the sugar into the water until dissolved, then add the ginger and lemon juices.$q$),
($q$House Ginger Beer$q$, 2, $q$Chill the mix until very cold, close to 0 C. Cold liquid holds more gas.$q$),
($q$House Ginger Beer$q$, 3, $q$Carbonate in a soda siphon or carbonation rig following the maker's instructions.$q$),
($q$House Ginger Beer$q$, 4, $q$Keep sealed and cold. Use within three days.$q$),
($q$Jalapeño Syrup$q$, 0, $q$Heat the water and sugar, stirring, until dissolved and just simmering.$q$),
($q$Jalapeño Syrup$q$, 1, $q$Take off the heat, add the sliced jalapeño and steep. Taste after 10 minutes and strain earlier if it is hot enough.$q$),
($q$Jalapeño Syrup$q$, 2, $q$Strain, cool, bottle and keep in the fridge.$q$),
($q$Jalapeño-Infused Tequila$q$, 0, $q$Slice the jalapeños and add them, seeds and all, to the tequila in a clean jar.$q$),
($q$Jalapeño-Infused Tequila$q$, 1, $q$Infuse at room temperature, tasting often. Heat varies a lot from one jalapeño to the next.$q$),
($q$Jalapeño-Infused Tequila$q$, 2, $q$Strain through a fine sieve once it is spicy enough.$q$),
($q$Jalapeño-Infused Tequila$q$, 3, $q$Bottle and label.$q$),
($q$Lactic Acid Solution (10%)$q$, 0, $q$Weigh the lactic acid and the water accurately.$q$),
($q$Lactic Acid Solution (10%)$q$, 1, $q$Stir or shake until completely dissolved and clear.$q$),
($q$Lactic Acid Solution (10%)$q$, 2, $q$Bottle and label clearly with the name, strength and date.$q$),
($q$Lavender Syrup$q$, 0, $q$Heat the water and sugar, stirring, until dissolved and just simmering.$q$),
($q$Lavender Syrup$q$, 1, $q$Take off the heat, stir in the lavender, cover and steep. Longer steeping turns it soapy.$q$),
($q$Lavender Syrup$q$, 2, $q$Strain through a fine sieve, cool, bottle and keep in the fridge.$q$),
($q$Lemon Sherbet$q$, 0, $q$Muddle the lemon peels with the sugar, cover and rest until the sugar is wet and oily.$q$),
($q$Lemon Sherbet$q$, 1, $q$Add the lemon juice and stir until all the sugar has dissolved.$q$),
($q$Lemon Sherbet$q$, 2, $q$Strain out the peels, pressing them well.$q$),
($q$Lemon Sherbet$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Lemongrass Syrup$q$, 0, $q$Heat the water and sugar, stirring, until dissolved.$q$),
($q$Lemongrass Syrup$q$, 1, $q$Add the bruised, chopped lemongrass and simmer gently.$q$),
($q$Lemongrass Syrup$q$, 2, $q$Take off the heat, cover and steep.$q$),
($q$Lemongrass Syrup$q$, 3, $q$Strain through a fine sieve, cool, bottle and keep in the fridge.$q$),
($q$Lightly Whipped Cream$q$, 0, $q$Pour the cold cream into a shaker tin, squeeze bottle or bowl.$q$),
($q$Lightly Whipped Cream$q$, 1, $q$Shake or whisk until it thickens to the texture of pouring yoghurt. It should ribbon off a spoon, not hold peaks.$q$),
($q$Lightly Whipped Cream$q$, 2, $q$Keep cold. Pour slowly over the back of a warm spoon to float it on the drink.$q$),
($q$Lime Acid$q$, 0, $q$Weigh the water and both acids accurately.$q$),
($q$Lime Acid$q$, 1, $q$Stir or shake until the powders have completely dissolved and the liquid is clear.$q$),
($q$Lime Acid$q$, 2, $q$Bottle and label clearly with the name and date. Use measure for measure where a recipe needs the acidity of lime juice.$q$),
($q$Lime Cordial$q$, 0, $q$Peel the limes thinly before juicing them, avoiding the white pith.$q$),
($q$Lime Cordial$q$, 1, $q$Stir the sugar into the lime juice, without heat, until fully dissolved.$q$),
($q$Lime Cordial$q$, 2, $q$Add the peels, cover and steep in the fridge.$q$),
($q$Lime Cordial$q$, 3, $q$Strain out the peels, bottle and keep in the fridge.$q$),
($q$Maple Syrup Mix$q$, 0, $q$Measure the maple syrup and water into a container.$q$),
($q$Maple Syrup Mix$q$, 1, $q$Stir or shake until evenly mixed.$q$),
($q$Maple Syrup Mix$q$, 2, $q$Bottle, label with the date and keep in the fridge. Diluted maple spoils faster than the pure syrup.$q$),
($q$Michelada Mix$q$, 0, $q$Juice and fine strain the limes.$q$),
($q$Michelada Mix$q$, 1, $q$Combine all the ingredients and stir well.$q$),
($q$Michelada Mix$q$, 2, $q$Bottle and keep in the fridge. Shake before each use.$q$),
($q$Mint Syrup$q$, 0, $q$Blanch the mint leaves in boiling water, then move them straight into iced water. This sets the green colour.$q$),
($q$Mint Syrup$q$, 1, $q$Squeeze the leaves dry and blend with the cold simple syrup until smooth.$q$),
($q$Mint Syrup$q$, 2, $q$Strain through a fine cloth or coffee filter.$q$),
($q$Mint Syrup$q$, 3, $q$Bottle and keep in the fridge. The colour and freshness fade after about a week.$q$),
($q$Muscovado Syrup$q$, 0, $q$Break up any lumps in the muscovado, then combine with the hot water.$q$),
($q$Muscovado Syrup$q$, 1, $q$Stir over low heat until fully dissolved.$q$),
($q$Muscovado Syrup$q$, 2, $q$Strain through a fine sieve to catch undissolved lumps, cool, bottle and keep in the fridge.$q$),
($q$Oleo Saccharum$q$, 0, $q$Peel the lemons with a vegetable peeler, taking as little white pith as possible.$q$),
($q$Oleo Saccharum$q$, 1, $q$Toss the peels with the sugar and muddle firmly to bruise them.$q$),
($q$Oleo Saccharum$q$, 2, $q$Cover (or vacuum seal) and rest at room temperature until the sugar has turned into a wet, oily syrup. Stir once or twice.$q$),
($q$Oleo Saccharum$q$, 3, $q$Strain off the peels, pressing to collect all the syrup. Dissolve any remaining sugar with a splash of lemon juice or hot water if needed.$q$),
($q$Olive Oil-Washed Gin$q$, 0, $q$Combine the gin and olive oil in a wide container, seal and shake hard.$q$),
($q$Olive Oil-Washed Gin$q$, 1, $q$Leave at room temperature, shaking now and then.$q$),
($q$Olive Oil-Washed Gin$q$, 2, $q$Freeze until the oil has set into a firm layer.$q$),
($q$Olive Oil-Washed Gin$q$, 3, $q$Working quickly while it is still frozen, strain the gin through a coffee filter. Bottle and keep in the fridge.$q$),
($q$Orgeat$q$, 0, $q$Blend the toasted almonds with the hot water until finely ground.$q$),
($q$Orgeat$q$, 1, $q$Leave the almond mixture to steep.$q$),
($q$Orgeat$q$, 2, $q$Strain through a nut milk bag or cloth, squeezing out all the almond milk. You should have about 500 ml.$q$),
($q$Orgeat$q$, 3, $q$Stir the sugar into the almond milk over very low heat until dissolved. Do not boil.$q$),
($q$Orgeat$q$, 4, $q$Cool, stir in the orange flower water, bottle and keep in the fridge. It separates naturally; shake before use.$q$),
($q$Pandan Syrup$q$, 0, $q$Heat the water and sugar, stirring, until dissolved.$q$),
($q$Pandan Syrup$q$, 1, $q$Add the chopped pandan leaves and simmer gently.$q$),
($q$Pandan Syrup$q$, 2, $q$Take off the heat, cover and steep.$q$),
($q$Pandan Syrup$q$, 3, $q$Strain through a fine sieve, cool, bottle and keep in the fridge.$q$),
($q$Passion Fruit Cordial$q$, 0, $q$Stir the sugar and citric acid into the hot water until dissolved.$q$),
($q$Passion Fruit Cordial$q$, 1, $q$Leave to cool, then stir in the passion fruit purée.$q$),
($q$Passion Fruit Cordial$q$, 2, $q$Fine strain if you want it clear of pulp, bottle and keep in the fridge. Shake before use.$q$),
($q$Passion Fruit Syrup$q$, 0, $q$Heat the sugar and water gently, stirring, until dissolved. Leave to cool.$q$),
($q$Passion Fruit Syrup$q$, 1, $q$Stir the cooled syrup into the passion fruit purée until even.$q$),
($q$Passion Fruit Syrup$q$, 2, $q$Bottle and keep in the fridge. Shake before use.$q$),
($q$Peach Syrup$q$, 0, $q$Heat the water and sugar, stirring, until dissolved.$q$),
($q$Peach Syrup$q$, 1, $q$Add the sliced peaches and simmer very gently until soft.$q$),
($q$Peach Syrup$q$, 2, $q$Take off the heat, cover and steep as it cools.$q$),
($q$Peach Syrup$q$, 3, $q$Strain through a fine sieve, pressing lightly, then bottle and keep in the fridge.$q$),
($q$Piña Colada Mix$q$, 0, $q$Warm the tin of cream of coconut in hot water and stir until smooth.$q$),
($q$Piña Colada Mix$q$, 1, $q$Blend all the ingredients briefly until fully combined.$q$),
($q$Piña Colada Mix$q$, 2, $q$Bottle and keep in the fridge. Shake hard before each use as the coconut fat separates.$q$),
($q$Pineapple Shrub$q$, 0, $q$Toss the pineapple with the sugar, cover and rest in the fridge until the sugar has drawn out a thick syrup.$q$),
($q$Pineapple Shrub$q$, 1, $q$Strain through a fine sieve, pressing the fruit and scraping in any undissolved sugar.$q$),
($q$Pineapple Shrub$q$, 2, $q$Add the vinegar and stir or shake until all the sugar has dissolved.$q$),
($q$Pineapple Shrub$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Pineapple Syrup$q$, 0, $q$Stir the sugar into the water until dissolved to make a simple syrup.$q$),
($q$Pineapple Syrup$q$, 1, $q$Pour the syrup over the pineapple chunks, cover and steep in the fridge.$q$),
($q$Pineapple Syrup$q$, 2, $q$Strain, pressing the fruit gently to release the syrup.$q$),
($q$Pineapple Syrup$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Pineapple-Infused Rum$q$, 0, $q$Combine the pineapple and rum in a clean jar and seal.$q$),
($q$Pineapple-Infused Rum$q$, 1, $q$Infuse in the fridge for 3 to 5 days, shaking daily. Taste from day 3.$q$),
($q$Pineapple-Infused Rum$q$, 2, $q$Strain through a fine sieve, then a coffee filter, pressing the fruit lightly.$q$),
($q$Pineapple-Infused Rum$q$, 3, $q$Bottle, label and keep in the fridge.$q$),
($q$Raspberry Cordial$q$, 0, $q$Crush the raspberries with the sugar and leave until the juices run.$q$),
($q$Raspberry Cordial$q$, 1, $q$Add the hot water and citric acid and stir until everything has dissolved.$q$),
($q$Raspberry Cordial$q$, 2, $q$Strain through a fine sieve or cloth without pressing hard.$q$),
($q$Raspberry Cordial$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Raspberry Shrub$q$, 0, $q$Crush the raspberries with the sugar, cover and rest in the fridge until the sugar has drawn out a thick syrup.$q$),
($q$Raspberry Shrub$q$, 1, $q$Strain through a fine sieve, pressing the fruit and scraping in any undissolved sugar.$q$),
($q$Raspberry Shrub$q$, 2, $q$Add the vinegar and stir or shake until all the sugar has dissolved.$q$),
($q$Raspberry Shrub$q$, 3, $q$Bottle and keep in the fridge. The flavour mellows and improves after a few days.$q$),
($q$Raspberry Syrup$q$, 0, $q$Lightly crush the raspberries with the sugar and leave until the juices run.$q$),
($q$Raspberry Syrup$q$, 1, $q$Add the hot water and stir until all the sugar has dissolved.$q$),
($q$Raspberry Syrup$q$, 2, $q$Strain through a fine sieve or cloth. Let it drip rather than pressing hard, which makes the syrup cloudy.$q$),
($q$Raspberry Syrup$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Rhubarb Syrup$q$, 0, $q$Trim away all the leaves (they are not edible) and chop the stalks.$q$),
($q$Rhubarb Syrup$q$, 1, $q$Combine the rhubarb, sugar and water and simmer gently until the rhubarb is soft and has given up its colour.$q$),
($q$Rhubarb Syrup$q$, 2, $q$Strain through a fine sieve and let it drip without pressing, to keep the syrup clear.$q$),
($q$Rhubarb Syrup$q$, 3, $q$Cool, bottle and keep in the fridge.$q$),
($q$Rich Demerara Syrup$q$, 0, $q$Combine the demerara sugar and water in a pan over low heat.$q$),
($q$Rich Demerara Syrup$q$, 1, $q$Stir until completely dissolved, without letting it boil.$q$),
($q$Rich Demerara Syrup$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge.$q$),
($q$Rich Simple Syrup$q$, 0, $q$Combine the sugar and water in a pan over low heat.$q$),
($q$Rich Simple Syrup$q$, 1, $q$Stir until every crystal has dissolved and the syrup is clear. Take it off the heat before it simmers.$q$),
($q$Rich Simple Syrup$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge.$q$),
($q$Rosemary Syrup$q$, 0, $q$Heat the water and sugar, stirring, until dissolved and just simmering.$q$),
($q$Rosemary Syrup$q$, 1, $q$Take off the heat, add the rosemary, cover and steep.$q$),
($q$Rosemary Syrup$q$, 2, $q$Strain, cool, bottle and keep in the fridge.$q$),
($q$Saline Solution (10%)$q$, 0, $q$Weigh the salt and the warm water.$q$),
($q$Saline Solution (10%)$q$, 1, $q$Stir or shake until the salt has completely dissolved and the liquid is clear.$q$),
($q$Saline Solution (10%)$q$, 2, $q$Decant into a dropper or dasher bottle and label with the strength and date.$q$),
($q$Saline Solution (20%)$q$, 0, $q$Weigh the salt and the warm water.$q$),
($q$Saline Solution (20%)$q$, 1, $q$Stir or shake until the salt has completely dissolved and the liquid is clear.$q$),
($q$Saline Solution (20%)$q$, 2, $q$Decant into a dropper or dasher bottle and label with the strength and date.$q$),
($q$Salt Air$q$, 0, $q$Combine the water, lime juice, salt and lecithin in a wide, deep container and stir until the salt has dissolved.$q$),
($q$Salt Air$q$, 1, $q$Tilt the container and run a stick blender just at the surface to pull in air until a thick layer of foam builds up.$q$),
($q$Salt Air$q$, 2, $q$Let the foam settle for a minute so it firms up, then spoon it onto the drink.$q$),
($q$Salt Air$q$, 3, $q$Blend again to make more foam as needed during service.$q$),
($q$Sangrita$q$, 0, $q$Juice and fine strain the orange and lime.$q$),
($q$Sangrita$q$, 1, $q$Combine everything in a jug and stir until the salt has dissolved.$q$),
($q$Sangrita$q$, 2, $q$Taste and adjust the heat, salt and sweetness. It should be tart, savoury and lightly spicy.$q$),
($q$Sangrita$q$, 3, $q$Bottle, chill well and keep in the fridge.$q$),
($q$Simple Syrup$q$, 0, $q$Weigh the sugar and the water into a clean container. Use equal weights.$q$),
($q$Simple Syrup$q$, 1, $q$Stir or blend until the sugar has fully dissolved and the syrup is clear. Hot water speeds this up; do not boil or the ratio will drift.$q$),
($q$Simple Syrup$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge.$q$),
($q$Sour Mix$q$, 0, $q$Juice and fine strain the lemons and limes.$q$),
($q$Sour Mix$q$, 1, $q$Combine the juices with the simple syrup and stir.$q$),
($q$Sour Mix$q$, 2, $q$Bottle, label with the date and keep in the fridge. Best used within a day.$q$),
($q$Spiced Syrup$q$, 0, $q$Simmer the water with the spices and orange peel, covered.$q$),
($q$Spiced Syrup$q$, 1, $q$Take off the heat, add the sugar and stir until dissolved.$q$),
($q$Spiced Syrup$q$, 2, $q$Cover and steep as it cools.$q$),
($q$Spiced Syrup$q$, 3, $q$Strain through a fine sieve, bottle and keep in the fridge.$q$),
($q$Strawberry Shrub$q$, 0, $q$Toss the strawberries with the sugar, cover and rest in the fridge until the sugar has drawn out a thick syrup.$q$),
($q$Strawberry Shrub$q$, 1, $q$Strain through a fine sieve, pressing the fruit and scraping in any undissolved sugar.$q$),
($q$Strawberry Shrub$q$, 2, $q$Add the vinegar and stir or shake until all the sugar has dissolved.$q$),
($q$Strawberry Shrub$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Strawberry Syrup$q$, 0, $q$Toss the sliced strawberries with the sugar and leave until the juices run.$q$),
($q$Strawberry Syrup$q$, 1, $q$Add the hot water and stir until all the sugar has dissolved.$q$),
($q$Strawberry Syrup$q$, 2, $q$Strain through a fine sieve or cloth without pressing hard.$q$),
($q$Strawberry Syrup$q$, 3, $q$Bottle and keep in the fridge.$q$),
($q$Strawberry-Infused Campari$q$, 0, $q$Combine the sliced strawberries and Campari in a clean jar and seal.$q$),
($q$Strawberry-Infused Campari$q$, 1, $q$Infuse in the fridge for 24 to 48 hours, shaking once or twice.$q$),
($q$Strawberry-Infused Campari$q$, 2, $q$Strain through a fine sieve, then a coffee filter, without pressing the fruit.$q$),
($q$Strawberry-Infused Campari$q$, 3, $q$Bottle, label and keep in the fridge.$q$),
($q$Super Lemon Juice$q$, 0, $q$Weigh the lemon peels. The recipe scales from them: 1 g citric acid and 16.6 ml water per gram of peel.$q$),
($q$Super Lemon Juice$q$, 1, $q$Toss the peels with the citric acid in a container, cover and rest until a slick of oily liquid has formed.$q$),
($q$Super Lemon Juice$q$, 2, $q$Add the water and blend with a stick blender until the peels are finely chopped.$q$),
($q$Super Lemon Juice$q$, 3, $q$Strain through a fine cloth or superbag, squeezing it out.$q$),
($q$Super Lemon Juice$q$, 4, $q$Juice the peeled lemons, add the juice, bottle and keep in the fridge.$q$),
($q$Super Lime Juice$q$, 0, $q$Weigh the lime peels. The recipe scales from them: 0.66 g citric acid, 0.33 g malic acid and 16.6 ml water per gram of peel.$q$),
($q$Super Lime Juice$q$, 1, $q$Toss the peels with both acids in a container, cover and rest until a slick of oily liquid has formed.$q$),
($q$Super Lime Juice$q$, 2, $q$Add the water and blend with a stick blender until the peels are finely chopped.$q$),
($q$Super Lime Juice$q$, 3, $q$Strain through a fine cloth or superbag, squeezing it out.$q$),
($q$Super Lime Juice$q$, 4, $q$Juice the peeled limes, add the juice, bottle and keep in the fridge.$q$),
($q$Tea-Infused Vermouth$q$, 0, $q$Add the loose tea to the vermouth in a clean jar, seal and shake.$q$),
($q$Tea-Infused Vermouth$q$, 1, $q$Infuse at room temperature. Taste at 20 minutes; too long makes it bitter.$q$),
($q$Tea-Infused Vermouth$q$, 2, $q$Strain through a fine sieve and then a coffee filter, without squeezing the leaves.$q$),
($q$Tea-Infused Vermouth$q$, 3, $q$Bottle, label and keep in the fridge like any opened vermouth.$q$),
($q$Tepache$q$, 0, $q$Dissolve the piloncillo in the water in a clean, sanitised jar. Add the pineapple rind and core, cinnamon and cloves.$q$),
($q$Tepache$q$, 1, $q$Cover with a cloth and leave at room temperature for 2 to 3 days. Skim off any white foam each day.$q$),
($q$Tepache$q$, 2, $q$Taste daily. It is ready when lightly fizzy, sweet and tangy. Throw it away if it grows fuzzy mould or smells unpleasant.$q$),
($q$Tepache$q$, 3, $q$Strain through a fine cloth, bottle and refrigerate. It keeps fermenting slowly, so leave the lid loose or vent the bottle daily.$q$),
($q$Thyme Syrup$q$, 0, $q$Heat the water and sugar, stirring, until dissolved and just simmering.$q$),
($q$Thyme Syrup$q$, 1, $q$Take off the heat, add the thyme, cover and steep.$q$),
($q$Thyme Syrup$q$, 2, $q$Strain, cool, bottle and keep in the fridge.$q$),
($q$Tom and Jerry Batter$q$, 0, $q$Separate the eggs. Whisk the whites in a clean bowl to stiff peaks.$q$),
($q$Tom and Jerry Batter$q$, 1, $q$In another bowl, beat the yolks with the sugar, rum, vanilla and spices until thick and pale.$q$),
($q$Tom and Jerry Batter$q$, 2, $q$Fold the whites gently into the yolk mixture until even.$q$),
($q$Tom and Jerry Batter$q$, 3, $q$Keep chilled and use the same day. Contains raw egg; tell guests.$q$),
($q$Tom and Jerry Batter$q$, 4, $q$To serve, put 60 ml of batter in a warm mug with 30 ml rum and 30 ml brandy, then top with hot milk while stirring.$q$),
($q$Tonic Syrup$q$, 0, $q$Weigh the cinchona bark exactly; do not add extra. Simmer the water, bark, lemongrass, citrus peels and allspice, covered.$q$),
($q$Tonic Syrup$q$, 1, $q$Cool, then strain through a fine sieve to remove the solids.$q$),
($q$Tonic Syrup$q$, 2, $q$Filter again through a paper coffee filter until the liquid is clear and free of all bark particles. This step matters: no bark should reach the glass.$q$),
($q$Tonic Syrup$q$, 3, $q$Stir in the sugar, citric acid and salt until dissolved, warming gently if needed.$q$),
($q$Tonic Syrup$q$, 4, $q$Bottle and keep in the fridge. Serve 25 ml syrup to 100 ml soda water and do not exceed that strength.$q$),
($q$Vanilla Syrup$q$, 0, $q$Combine the sugar, water, vanilla seeds and pods in a pan.$q$),
($q$Vanilla Syrup$q$, 1, $q$Warm over low heat, stirring, until the sugar has dissolved. Do not boil.$q$),
($q$Vanilla Syrup$q$, 2, $q$Cover and leave to steep as it cools.$q$),
($q$Vanilla Syrup$q$, 3, $q$Strain out the pods, bottle and keep in the fridge.$q$),
($q$Vanilla Tincture$q$, 0, $q$Split the vanilla pods lengthways, chop them and put them in a clean jar with the vodka.$q$),
($q$Vanilla Tincture$q$, 1, $q$Seal and infuse at room temperature for about 14 days, shaking every day or two.$q$),
($q$Vanilla Tincture$q$, 2, $q$Strain through a coffee filter into dropper bottles and label.$q$),
($q$Vanilla-Infused Vodka$q$, 0, $q$Split the vanilla pods lengthways and drop them into the vodka.$q$),
($q$Vanilla-Infused Vodka$q$, 1, $q$Seal and infuse at room temperature for 3 to 5 days, shaking daily.$q$),
($q$Vanilla-Infused Vodka$q$, 2, $q$Strain through a fine sieve once the flavour is full, then bottle and label.$q$);
